    cwd: root,
    stdio: ["ignore", "pipe", "pipe"],
    windowsHide: true,
    env: { ...process.env, JI_STAGE1_TOKEN_PORT: String(tokenPort), JI_STAGE1_BASE_URL: origin },
  });
